/** Pinned full original writer shapes/actual native codecs. Public fixture is shared with ROOT's actual PlayerDataStorage gate tests. */
public final class NeoForgePlayerDataGameTests {
    private static ListTag rows(Tag... values){var result=new ListTag();for(var value:values)result.add(value);return result;}
    private static ListTag vector(double x,double y,double z){return rows(DoubleTag.valueOf(x),DoubleTag.valueOf(y),DoubleTag.valueOf(z));}
    private static CompoundTag xyz(BlockPos position){var value=new CompoundTag();value.putInt("X",position.getX());value.putInt("Y",position.getY());value.putInt("Z",position.getZ());return value;}
    private static CompoundTag item(String id,int count,int slot){var value=new CompoundTag();value.putString("id",id);value.putInt("count",count);value.putByte("Slot",(byte)slot);return value;}
    private static CompoundTag attribute(String id,double base){var value=new CompoundTag();value.putString("id",id);value.putDouble("base",base);return value;}
    private static CompoundTag base(GameTestHelper h,UUID actualUuid){var value=new CompoundTag();value.store("UUID",UUIDUtil.CODEC,actualUuid);var pos=Vec3.atBottomCenterOf(h.absolutePos(new BlockPos(3,3,3)));value.put("Pos",vector(pos.x,pos.y,pos.z));value.put("Motion",vector(0,0,0));value.put("Rotation",rows(FloatTag.valueOf(0),FloatTag.valueOf(0)));value.putFloat("FallDistance",0);value.putShort("Fire",(short)-1);value.putShort("Air",(short)300);value.putBoolean("OnGround",false);value.putBoolean("Invulnerable",false);value.putInt("PortalCooldown",0);return value;}
    /** Complete actual3955 player writer fixture; caller supplies the exact genuine source filename UUID. */
    public static CompoundTag original(GameTestHelper h,UUID actualFilenameUuid){
        var source=base(h,actualFilenameUuid);source.putInt("DataVersion",3955);source.putString("Dimension",h.getLevel().dimension().identifier().toString());
        source.put("Inventory",rows(item("minecraft:diamond",11,0),item("minecraft:gold_ingot",5,35),item("minecraft:leather_boots",1,100),item("minecraft:iron_helmet",1,103),item("minecraft:shield",1,150)));source.put("EnderItems",rows(item("minecraft:emerald",7,26)));
        source.putInt("SelectedItemSlot",0);source.putShort("SleepTimer",(short)0);source.putFloat("XpP",.25f);source.putInt("XpLevel",7);source.putInt("XpTotal",123);source.putInt("XpSeed",17);source.putInt("Score",9);source.putInt("foodLevel",18);source.putInt("foodTickTimer",5);source.putFloat("foodSaturationLevel",4);source.putFloat("foodExhaustionLevel",1);
        var abilities=new CompoundTag();for(String key:Set.of("invulnerable","flying","mayfly","instabuild"))abilities.putBoolean(key,false);abilities.putBoolean("mayBuild",true);abilities.putFloat("flySpeed",.05f);abilities.putFloat("walkSpeed",.1f);source.put("abilities",abilities);
        source.putFloat("Health",13);source.putFloat("AbsorptionAmount",2);source.putShort("HurtTime",(short)3);source.putShort("DeathTime",(short)0);source.putInt("HurtByTimestamp",17);source.putBoolean("FallFlying",false);var brain=new CompoundTag();brain.put("memories",new CompoundTag());source.put("Brain",brain);
        source.put("attributes",rows(attribute("minecraft:generic.max_health",20),attribute("minecraft:generic.movement_speed",.1),attribute("minecraft:player.block_interaction_range",12),attribute("minecraft:player.entity_interaction_range",3),attribute("minecraft:generic.gravity",.08),attribute("neoforge:nametag_distance",32),attribute("neoforge:swim_speed",1),attribute("neoforge:creative_flight",0)));
        source.putInt("playerGameType",0);source.putBoolean("seenCredits",false);source.putBoolean("spawn_extra_particles_on_fall",false);var tracker=new CompoundTag();tracker.putInt("ticks_since_last_warning",0);tracker.putInt("warning_level",0);tracker.putInt("cooldown_ticks",0);source.put("warden_spawn_tracker",tracker);
        var recipes=new CompoundTag();recipes.put("recipes",new ListTag());recipes.put("toBeDisplayed",new ListTag());for(String key:Set.of("isGuiOpen","isFilteringCraftable","isFurnaceGuiOpen","isFurnaceFilteringCraftable","isBlastingFurnaceGuiOpen","isBlastingFurnaceFilteringCraftable","isSmokerGuiOpen","isSmokerFilteringCraftable"))recipes.putBoolean(key,false);source.put("recipeBook",recipes);return source;
    }
    /** The genuine complete source Seat RootVehicle has no fabricated physical player body. */
    public static CompoundTag withSeatVehicle(GameTestHelper h,CompoundTag completeOriginal){var source=completeOriginal.copy();var body=base(h,UUID.randomUUID());body.putString("id","create:seat");var vehicle=new CompoundTag();vehicle.store("Attach",UUIDUtil.CODEC,body.read("UUID",UUIDUtil.CODEC).orElseThrow());vehicle.put("Entity",body);source.put("RootVehicle",vehicle);return source;}
    private static ItemStack at(GameTestHelper h,CompoundTag source,String field,int slot){return source.getListOrEmpty(field).stream().map(value->ItemStackWithSlot.CODEC.parse(h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE),value).getOrThrow()).filter(value->value.slot()==slot).findFirst().orElseThrow().stack();}
    private static void refuses(GameTestHelper h,CompoundTag source,UUID file,String description){var before=source.copy();boolean refused=false;try{NeoForgePlayerDataImport.convert(source,file,h.getLevel());}catch(RuntimeException expected){refused=true;}h.assertTrue(refused&&source.equals(before),description);}
    @GameTest public void exactSparseMainArmorOffhandAndEnderSlotsReachActualNativeCodecsWithoutMaterialRemainders(GameTestHelper h){
        var file=UUID.randomUUID();var source=withSeatVehicle(h,original(h,file));var before=source.copy();var current=NeoForgePlayerDataImport.convert(source,file,h.getLevel());var equipment=current.getCompoundOrEmpty("equipment");EntityEquipment.CODEC.parse(h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE),equipment).getOrThrow();
        h.assertTrue(source.equals(before)&&current.getInt("DataVersion").orElseThrow()==net.minecraft.SharedConstants.getCurrentVersion().dataVersion().version()&&current.getListOrEmpty("Inventory").size()==2&&at(h,current,"Inventory",0).is(Items.DIAMOND)&&at(h,current,"Inventory",0).getCount()==11&&at(h,current,"Inventory",35).getCount()==5&&at(h,current,"EnderItems",26).is(Items.EMERALD)&&at(h,current,"EnderItems",26).getCount()==7,"One real original PLAYER fixer retains every genuine source sparse physical item and keeps source compounds untouched");
        h.assertTrue(equipment.keySet().equals(Set.of("feet","head","offhand"))&&ItemStack.CODEC.parse(h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE),equipment.get("feet")).getOrThrow().is(Items.LEATHER_BOOTS)&&ItemStack.CODEC.parse(h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE),equipment.get("head")).getOrThrow().is(Items.IRON_HELMET)&&ItemStack.CODEC.parse(h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE),equipment.get("offhand")).getOrThrow().is(Items.SHIELD)&&current.getCompoundOrEmpty("RootVehicle").getCompoundOrEmpty("Entity").get("UUID").equals(source.getCompoundOrEmpty("RootVehicle").getCompoundOrEmpty("Entity").get("UUID")),"Original source byte100/103/150 become real native equipment once, with separately converted actual original RootVehicle identity");h.succeed();
    }
    @GameTest public void originalCoreToolboxGroundedAndEffectsKeepRealValuesWhileHistoryNeverInventsAttackers(GameTestHelper h){
        var file=UUID.randomUUID();var source=original(h,file);var data=new CompoundTag();var bindings=new CompoundTag();var binding=new CompoundTag();binding.putInt("Slot",6);binding.put("Pos",xyz(h.absolutePos(new BlockPos(2,2,2))));bindings.put("8",binding);data.put("CreateToolboxData",bindings);data.putBoolean("LavaGrounded",true);data.putBoolean("ContraptionGrounded",true);data.putBoolean("createExtendo",true);source.put("NeoForgeData",data);
        var effect=new CompoundTag();effect.putString("id","minecraft:poison");effect.putByte("amplifier",(byte)0);effect.putInt("duration",200);effect.putBoolean("ambient",false);effect.putBoolean("show_particles",true);effect.putBoolean("show_icon",true);effect.put("neoforge:cures",rows(StringTag.valueOf("milk"),StringTag.valueOf("protected_by_totem"),StringTag.valueOf("honey")));source.put("active_effects",rows(effect));
        var current=NeoForgePlayerDataImport.convert(source,file,h.getLevel());var history=NeoForgePlayerHistory.read(current.getCompoundOrEmpty(NeoForgePlayerHistory.KEY));var nativeBinding=current.getCompoundOrEmpty("fabric:attachments").getCompoundOrEmpty("create:toolbox_bindings").getCompoundOrEmpty("8");
        h.assertTrue(history.originalCoreData().equals(data)&&history.originalAttributes().equals(source.getListOrEmpty("attributes"))&&history.hurtByTimestamp()==17&&nativeBinding.getInt("Slot").orElseThrow()==6&&nativeBinding.read("Pos",BlockPos.CODEC).orElseThrow().equals(h.absolutePos(new BlockPos(2,2,2)))&&!nativeBinding.contains("Owner")&&current.getBooleanOr("CreateArmorLavaGrounded",false)&&current.getBooleanOr("CreatePassengerGrounded",false)&&!current.contains("NeoForgeData")&&!current.contains("HurtByTimestamp")&&!current.contains("last_hurt_by_mob"),"Exact original toolbox position/compartment and native active grounded values survive; no original toolbox owner or attacker UUID/timing proof is invented");
        var attrs=current.getListOrEmpty("attributes");h.assertTrue(attrs.size()==6&&attrs.stream().anyMatch(value->((CompoundTag)value).getStringOr("id","").equals("minecraft:name_tag_distance"))&&attrs.stream().anyMatch(value->((CompoundTag)value).getStringOr("id","").equals("minecraft:block_interaction_range")&&((CompoundTag)value).getDoubleOr("base",0)==12)&&!current.getListOrEmpty("active_effects").getCompoundOrEmpty(0).contains("neoforge:cures"),"Real native reach/gravity/name-distance attributes retain values; only proven identity-default unmatched NeoForge attributes become inert exact history, and verified native-equivalent default effect cures are removed");h.succeed();
    }
    private static CompoundTag packed(){
        var state=new CompoundTag();state.putString("Name",BuiltInRegistries.BLOCK.getKey(AllBlocks.MINECART_ANCHOR).toString());var properties=new CompoundTag();AllBlocks.MINECART_ANCHOR.defaultBlockState().getValues().forEach(value->properties.putString(value.property().getName(),value.valueName()));if(!properties.isEmpty())state.put("Properties",properties);
        var block=new CompoundTag();block.putLong("Pos",BlockPos.ZERO.asLong());block.putInt("State",0);var blocks=new CompoundTag();blocks.put("Palette",rows(state));blocks.put("BlockList",rows(block));var body=new CompoundTag();body.putString("Type","create:mounted");body.putString("RotationMode","ROTATE");body.putString("InitialOrientation","EAST");body.put("Anchor",xyz(BlockPos.ZERO));body.putBoolean("Stalled",false);body.putBoolean("BottomlessSupply",false);body.put("Blocks",blocks);for(String key:Set.of("CapturedMultiblocks","Actors","DisabledActors","Interactors","Superglue","Seats","Passengers","SubContraptions"))body.put(key,new ListTag());var components=new CompoundTag();components.put("create:minecart_contraption_data",body);var item=new CompoundTag();item.putString("id","create:minecart_contraption");item.putInt("count",1);item.put("components",components);return item;
    }
    @GameTest public void sourcePlayerUuidAndActualSparseRoleSlotDetermineDistinctNewPackedValueIdentities(GameTestHelper h){
        var file=UUID.randomUUID();var source=original(h,file);var main=packed();main.putByte("Slot",(byte)35);source.getListOrEmpty("Inventory").set(1,main);var ender=packed();ender.putByte("Slot",(byte)26);source.put("EnderItems",rows(ender));var first=NeoForgePlayerDataImport.convert(source,file,h.getLevel());var repeat=NeoForgePlayerDataImport.convert(source,file,h.getLevel());
        var firstMain=at(h,first,"Inventory",35).get(AllDataComponents.MINECRAFT_CONTRAPTION_DATA);var firstEnder=at(h,first,"EnderItems",26).get(AllDataComponents.MINECRAFT_CONTRAPTION_DATA);var repeatMain=at(h,repeat,"Inventory",35).get(AllDataComponents.MINECRAFT_CONTRAPTION_DATA);
        h.assertTrue(firstMain.get("NativePlanId").equals(repeatMain.get("NativePlanId"))&&!firstMain.get("NativePlanId").equals(firstEnder.get("NativePlanId"))&&!firstMain.contains("CustodyReceipt")&&!firstEnder.contains("BaseCarts"),"Actual source player UUID + typed inventory/EnderItems + actual sparse slot establish distinct stable NEW value identities, never an original entity UUID or paid receipt");h.succeed();
    }
    @GameTest public void genuineCompleteShoulderBodyRetainsItsOwnSourceIdentityAndCannotAlsoOwnVehicleMaterial(GameTestHelper h){
        var file=UUID.randomUUID();var source=original(h,file);var shoulder=base(h,UUID.randomUUID());shoulder.putString("id","minecraft:parrot");shoulder.put("ArmorItems",rows(new CompoundTag(),new CompoundTag(),new CompoundTag(),new CompoundTag()));shoulder.put("HandItems",rows(new CompoundTag(),new CompoundTag()));shoulder.putFloat("Health",6);shoulder.putFloat("AbsorptionAmount",0);shoulder.putShort("HurtTime",(short)0);shoulder.putShort("DeathTime",(short)0);shoulder.putInt("HurtByTimestamp",0);shoulder.putBoolean("FallFlying",false);shoulder.put("attributes",new ListTag());var brain=new CompoundTag();brain.put("memories",new CompoundTag());shoulder.put("Brain",brain);shoulder.putInt("Variant",2);shoulder.putBoolean("Sitting",false);source.put("ShoulderEntityLeft",shoulder);
        var current=NeoForgePlayerDataImport.convert(source,file,h.getLevel());h.assertTrue(current.getCompoundOrEmpty("ShoulderEntityLeft").get("UUID").equals(shoulder.get("UUID"))&&current.getCompoundOrEmpty("ShoulderEntityLeft").getStringOr("id","").equals("minecraft:parrot")&&at(h,current,"Inventory",0).getCount()==11,"Complete genuine source shoulder tree is separately migrated from untouched original data, retaining its real UUID and one player inventory owner");
        var duplicate=withSeatVehicle(h,source);duplicate.getCompoundOrEmpty("RootVehicle").getCompoundOrEmpty("Entity").put("UUID",shoulder.get("UUID").copy());duplicate.getCompoundOrEmpty("RootVehicle").put("Attach",shoulder.get("UUID").copy());refuses(h,duplicate,file,"One actual source UUID cannot own both a serialized shoulder body and a separately loaded source vehicle body");h.succeed();
    }
    @GameTest public void malformedOrUnownedPlayerMaterialAndNonEquivalentSourceBehaviorRefuseBeforeAnyFactory(GameTestHelper h){
        var file=UUID.randomUUID();refuses(h,original(h,file),UUID.randomUUID(),"Actual source filename UUID must identify this complete genuine original player");var missing=original(h,file);missing.remove("Inventory");refuses(h,missing,file,"Missing actual source player inventory cannot become a fabricated empty inventory");
        var duplicate=original(h,file);duplicate.getListOrEmpty("Inventory").add(duplicate.getListOrEmpty("Inventory").getFirst().copy());refuses(h,duplicate,file,"Two source rows cannot own the same actual player slot");var unknown=original(h,file);var data=new CompoundTag();data.putString("UnreviewedOwnedInventory","must survive as a diagnosed owner, never ignored");unknown.put("NeoForgeData",data);refuses(h,unknown,file,"Unknown actual player persistent owner cannot be silently dropped");
        var swim=original(h,file);swim.getListOrEmpty("attributes").getCompoundOrEmpty(6).putDouble("base",2);refuses(h,swim,file,"Nondefault source swim acceleration/jump behavior cannot masquerade as unrelated native water movement efficiency");var custom=original(h,file);var effect=new CompoundTag();effect.putString("id","minecraft:speed");effect.put("neoforge:cures",new ListTag());custom.put("active_effects",rows(effect));refuses(h,custom,file,"Custom original effect cure semantics cannot silently become native defaults");h.succeed();
    }
}
